		/** 
		 * Tests creating a new APIClient.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a APIClient");

			StringBuilder msg = new StringBuilder( "-- Failed to create a APIClient" );

			try {            
				APIClient entity = APIClientService.getAPIClientInstance().createAPIClient( generateNewEntity() );
				thePrimaryKey = entity.getAPIClientId();
				LOGGER.info( "-- Successfully created a APIClient with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a APIClient. 
		 */
		public APIClient testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created APIClient" );

			APIClient entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read APIClient with primary key" );
			msg.append( thePrimaryKey );
			
			APIClientFetchOneSummary fetchOneSummary = new APIClientFetchOneSummary( thePrimaryKey );

			try {
				entity = APIClientService.getAPIClientInstance().getAPIClient( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found APIClient " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a APIClient.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a APIClient." );

			StringBuilder msg = new StringBuilder( "Failed to update a APIClient : " );        
			APIClient entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created APIClient." );

				// for use later on...
				thePrimaryKey = entity.getAPIClientId();

				APIClientService proxy = APIClientService.getAPIClientInstance();            
				proxy.updateAPIClient( entity );   

				LOGGER.info( "-- Successfully saved APIClient - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a APIClient.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created APIClient." );

			try{
			    APIClient entity = testRead(); 
				APIClientService.getAPIClientInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted APIClient with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete APIClient with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all APIClients.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of APIClients:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all APIClient : " );        
			List<APIClient> collection  = null;

			try {
				// call the static get method on the APIClientService
				collection = APIClientService.getAPIClientInstance().getAllAPIClient();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					APIClient entity = null;            
					Iterator<APIClient> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getAPIClientId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

